const recordUploadItemAttempt = `-- name: RecordUploadItemAttempt :exec
UPDATE skill.vocab_upload_items
SET attempts = attempts + 1,
    reason   = CASE WHEN attempts + 1 >= $1::int
                    THEN $2::text ELSE $3::text END,
    status   = CASE WHEN attempts + 1 >= $1::int
                    THEN 'failed' ELSE status END
WHERE id = $4 AND status = 'pending'
`

type RecordUploadItemAttemptParams struct {
	MaxAttempts     int32
	ExhaustedReason string
	Reason          string
	ID              uuid.UUID
}

// A transient failure — the dictionary was unreachable, the model timed out.
// The item stays pending so the next run retries it, until the attempt that
// reaches the limit: that one retires it as failed with the learner-facing
// reason. Retiring by status, not only by the claim's `attempts < limit`
// filter, is what keeps a word from showing "checking" for ever.
func (q *Queries) RecordUploadItemAttempt(ctx context.Context, arg RecordUploadItemAttemptParams) error {
	_, err := q.db.Exec(ctx, recordUploadItemAttempt,
		arg.MaxAttempts,
		arg.ExhaustedReason,
		arg.Reason,
		arg.ID,
	)
	return err
}

const searchUserUploadItems = `-- name: SearchUserUploadItems :many
SELECT
    i.id, i.upload_id, i.user_id, i.term, i.provided_meaning, i.status, i.reason, i.word_sense_id, i.verified_by_model, i.attempts, i.created_at, i.verified_at, i.corrected_term, i.suggested_term, i.note_code,
    s.definition,
    s.definition_vi,
    s.domain AS topic,
    s.examples
FROM skill.vocab_upload_items i
LEFT JOIN skill.word_senses s ON s.id = i.word_sense_id
WHERE i.user_id = $1
  AND ($2::uuid IS NULL OR i.upload_id = $2::uuid)
  AND (cardinality($3::text[]) = 0 OR i.status = ANY($3::text[]))
  AND ($4::text = ''
       OR i.term ILIKE '%' || $4::text || '%'
       OR i.corrected_term ILIKE '%' || $4::text || '%')
  AND ($5::timestamptz IS NULL
       OR i.created_at < $5::timestamptz
       OR (i.created_at = $5::timestamptz
           AND (i.term, i.id) > ($6::text, $7::uuid)))
ORDER BY i.created_at DESC, i.term, i.id
LIMIT $8
`

type SearchUserUploadItemsParams struct {
	UserID         uuid.UUID
	UploadID       *uuid.UUID
	Statuses       []string
	Query          string
	AfterCreatedAt *time.Time
	AfterTerm      *string
	AfterID        *uuid.UUID
	RowLimit       int32
}

type SearchUserUploadItemsRow struct {
	ID              uuid.UUID
	UploadID        uuid.UUID
	UserID          uuid.UUID
	Term            string
	ProvidedMeaning string
	Status          string
	Reason          string
	WordSenseID     *uuid.UUID
	VerifiedByModel string
	Attempts        int32
	CreatedAt       time.Time
	VerifiedAt      *time.Time
	CorrectedTerm   *string
	SuggestedTerm   *string
	NoteCode        *string
	Definition      *string
	DefinitionVi    *string
	Topic           *string
	Examples        []byte
}

// Every word a learner has pasted, across uploads: what the search box and an
// opened upload page through. Newest upload first, then alphabetical, keyset on
// (created_at, term, id). `query` arrives LIKE-escaped from the service.
func (q *Queries) SearchUserUploadItems(ctx context.Context, arg SearchUserUploadItemsParams) ([]SearchUserUploadItemsRow, error) {
	rows, err := q.db.Query(ctx, searchUserUploadItems,
		arg.UserID,
		arg.UploadID,
		arg.Statuses,
		arg.Query,
		arg.AfterCreatedAt,
		arg.AfterTerm,
		arg.AfterID,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SearchUserUploadItemsRow
	for rows.Next() {
		var i SearchUserUploadItemsRow
		if err := rows.Scan(
			&i.ID,
			&i.UploadID,
			&i.UserID,
			&i.Term,
			&i.ProvidedMeaning,
			&i.Status,
			&i.Reason,
			&i.WordSenseID,
			&i.VerifiedByModel,
			&i.Attempts,
			&i.CreatedAt,
			&i.VerifiedAt,
			&i.CorrectedTerm,
			&i.SuggestedTerm,
			&i.NoteCode,
			&i.Definition,
			&i.DefinitionVi,
			&i.Topic,
			&i.Examples,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

